#include <coroutine>
#include <exception>
#include <iostream>
#include <utility>
#include <string>

class Stepper {
public:
    struct promise_type;
    using Handle = std::coroutine_handle<promise_type>;
    struct promise_type {
        Stepper get_return_object() { return Stepper{Handle::from_promise(*this)}; }
        std::suspend_always initial_suspend() noexcept { return {}; }
        std::suspend_always final_suspend() noexcept { return {}; }
        void return_void() noexcept {}
        void unhandled_exception() { std::terminate(); }
    };
    explicit Stepper(Handle handle) : handle_{handle} {}
    Stepper(const Stepper&) = delete;
    Stepper& operator=(const Stepper&) = delete;
    Stepper(Stepper&& other) noexcept : handle_{std::exchange(other.handle_, {})} {}
    Stepper& operator=(Stepper&&) = delete;
    ~Stepper() { if (handle_) handle_.destroy(); }
    void resume() { if (handle_ && !handle_.done()) handle_.resume(); }
private:
    Handle handle_;
};

Stepper announce(std::string title)
{
    std::cout << title << '\n';
    co_await std::suspend_always{};
    std::cout << "finished\n";
}

int main()
{
    auto task = announce(std::string{"Atlas"});
    task.resume();
}
